cards.example:
for (let i = 0; i < 3; i++) {
  console.log("Привет");
}
// выведет «Привет» 3 раза

let i = 5;
i++; // теперь 6
i--; // снова 5

for (let i = 10; i < 5; i++) {
  console.log("не выведется");
}

for (let i = 0; i < 3; i++) {
  console.log(i); // это тело цикла
}

let i = 0;
while (i < 3) {
  console.log(i);
  // забыли i++, i всегда 0, цикл не кончится
}

let n = 10;
do {
  console.log(n); // выведется один раз
} while (n < 5);

const names = ["Аня", "Борис"];
for (const name of names) {
  console.log(name);
}

const user = { name: "Аня", age: 20 };
for (const key in user) {
  console.log(key, user[key]);
}

for (let i = 0; i < 10; i++) {
  if (i === 3) break;
  console.log(i); // 0, 1, 2
}

for (let i = 0; i < 5; i++) {
  if (i === 2) continue;
  console.log(i); // 0, 1, 3, 4
}

const arr = ["a", "b", "c"];
for (let i = 0; i < arr.length; i++) {
  console.log(i, arr[i]);
}

for (let row = 1; row <= 3; row++) {
  for (let col = 1; col <= 4; col++) {
    console.log(row, col);
  }
}

const arr = [1, 2, 3];
for (let i = 0; i <= arr.length; i++) {
  console.log(arr[i]); // 1, 2, 3, undefined
}

const nums = [2, 4, 6];
let sum = 0;
for (const n of nums) {
  sum = sum + n;
}
console.log(sum); // 12

// for: ровно 5 раз
for (let i = 0; i < 5; i++) { }

// while: пока не угадал
while (guess !== secret) { }
